-- quest-step row: chain, task var, value lo..hi, camp (-1 all), level, start-row flag + max level, destination,
-- text, item set, second task var lo2..hi2, extra condition, kill (fight / counter step: no item can replace it),
-- farm = "bai quai" destination (target of a fight step / where the step's quest items drop), m2 > 0: the
-- second task value is compared modulo m2 (lenhbainv2)
function PTNV_R(c, var, lo, hi, camp, lv, st, lvmax, dest, txt, set, v2, lo2, hi2, cond, kill, farm, m2)
	local r = {}
	r.var = var
	r.lo = lo
	r.hi = hi
	r.camp = camp
	r.lv = lv
	r.st = st
	r.lvmax = lvmax
	r.dest = dest
	r.txt = txt
	r.set = set
	r.v2 = v2
	r.lo2 = lo2
	r.hi2 = hi2
	r.cond = cond
	r.kill = kill
	r.farm = farm
	r.m2 = m2
	local t = PTNV_CH[c]
	t.n = t.n + 1
	t.r[t.n] = r
end

-- item: kind 1 event item (detail g), 2 VNG tuple g,d,p created at level lv, counted at level cl (-1 any),
-- 3 skill book (skill lv, book 6,1,p); n = count; cv/cb = only when bit cb of task cv is set
function PTNV_It(k, g, d, p, lv, n, cl, cv, cb, nm)
	local it = {}
	it.k = k
	it.g = g
	it.d = d
	it.p = p
	it.lv = lv
	it.n = n
	it.cl = cl
	it.cv = cv
	it.cb = cb
	it.nm = nm
	return it
end

function PTNV_I(s, k, g, d, p, lv, n, cl, cv, cb, nm)
	local t = PTNV_IS[s]
	if not t then
		t = {}
		t.n = 0
		PTNV_IS[s] = t
	end
	t.n = t.n + 1
	t[t.n] = PTNV_It(k, g, d, p, lv, n, cl, cv, cb, nm)
end

-- runtime row for the custom chains
function PTNV_Row(dest, txt, items, kill, lv, farm)
	local r = {}
	r.dest = dest
	r.txt = txt
	r.items = items
	r.set = 0
	r.kill = kill
	r.lv = lv
	r.farm = farm or 0
	return r
end

-- lenhbainv2: where the step sends the player now: the "bai quai" of a fight step, or of an item step while
-- items are still missing; otherwise the NPC. Returns destination index or 0.
function PTNV_Target(r)
	if r.farm and r.farm > 0 then
		if r.kill == 1 then return r.farm end
		if PTNV_Need(r).tot > 0 then return r.farm end
	end
	if r.dest and r.dest > 0 then return r.dest end
	if r.farm and r.farm > 0 then return r.farm end
	return 0
end

