function PTNV_Camp()
	local c = nil
	if GetPlayerType then c = GetPlayerType() end
	if c == nil or c < 0 or c > 2 then c = GetProfession() end
	if c == nil or c < 0 or c > 2 then c = 0 end
	return c
end

-- main-story task of the camp: Giap Si 3, Dao Si 1, Di Nhan 2
function PTNV_MainVar()
	local c = PTNV_Camp()
	if c == 0 then return 3 end
	return c
end

function PTNV_Bit(v, b)
	return mod(floor(v / b), 2) == 1
end

function PTNV_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

-- maps where the tokens work: field maps and cities 1001-1057, quest maps 1061-1065, Tien Ma / Luu Ba / Khong Tang
-- 1073-1078. Never from Thien Lao (1060), Truc Lung (1066), Van Tien (1067-1070, 1079-1082), battlefield (1071),
-- Khai Minh dao (1072), Huyen Vu and the instances 1083+.
function PTNV_SrcOk()
	local m = GetWorldPos()
	if not m then return nil end
	if m >= 1001 and m <= 1057 then return m end
	if m >= 1061 and m <= 1065 then return m end
	if m >= 1073 and m <= 1078 then return m end
	return nil
end

function PTNV_Blocked()
	Say(PTNV_T_BLOCKED, 1, PTNV_T_CLOSE .. "/" .. PTNV_NOFN)
end

-- quest-progress gates of the maps the chains reach through NPC teleports (same tests as those NPCs)
function PTNV_Gate(code)
	if code == 1 then return GetLevel() >= 75 and GetTask(2252) > 0 end
	if code == 2 then local t = GetTask(2222) return t == 14 or t >= 20 end
	if code == 3 then return GetTask(2222) >= 27 end
	if code == 4 then return GetTask(2283) >= 46 end
	if code == 5 then return GetTask(PTNV_MainVar()) >= 50 end
	if code == 6 then return GetTask(PTNV_MainVar()) >= 71 end
	if code == 7 then return GetTask(PTNV_MainVar()) >= 72 end
	if code == 8 then return GetTask(PTNV_MainVar()) >= 80 end
	if code == 9 then return GetTask(597) >= 9 end
	return 1
end

