function PTNV_Go(i)
	local d = PTNV_DS[i]
	if not d then return end
	if not PTNV_SrcOk() then PTNV_Blocked() return end
	if d.gate > 0 and not PTNV_Gate(d.gate) then
		Say(PTNV_T_GATE .. " " .. (PTNV_GATEMSG[d.gate] or ""), 1, PTNV_T_CLOSE .. "/" .. PTNV_NOFN)
		return
	end
	local sw = SubWorldID2Idx(d.map)
	if not sw or sw < 0 then
		Msg2Player(d.nm .. PTNV_T_NOMAP)
		return
	end
	if NewWorld(d.map, d.x, d.y) == 0 then
		Msg2Player(PTNV_T_NOGO .. d.nm .. ".")
		return
	end
	SetFightState(d.fight)
	Msg2Player(PTNV_T_ARRIVE .. d.nm .. " [" .. floor(d.x / 8) .. "," .. floor(d.y / 16) .. "].")
end

-- destinations of a group visible to the camp of the player
function PTNV_List(g)
	local camp = PTNV_Camp()
	local t = PTNV_GR[g]
	local o = {}
	local n = 0
	local k = 1
	while k <= t.n do
		local d = PTNV_DS[t[k]]
		if d.camp < 0 or d.camp == camp then
			n = n + 1
			o[n] = t[k]
		end
		k = k + 1
	end
	o.n = n
	return o
end

-- page p of n entries: 4 per page + next, or the last <= 5 entries; returns first, last, has-next
function PTNV_Span(n, p)
	local first = (p - 1) * 4 + 1
	if n - first + 1 <= 5 then return first, n, nil end
	return first, first + 3, 1
end

function PTNV_Page(g, p)
	local t = PTNV_List(g)
	local first, last, more = PTNV_Span(t.n, p)
	local lv = GetLevel()
	local o = {}
	local n = 0
	local i = first
	while i <= last do
		local d = PTNV_DS[t[i]]
		local s = d.nm .. " (" .. PTNV_T_LV .. d.lv .. ")"
		if lv < d.lv then s = s .. " *" end
		n = n + 1
		o[n] = s .. "/PTNV_G" .. t[i]
		i = i + 1
	end
	if more then n = n + 1 o[n] = PTNV_T_NEXT .. "/PTNV_P" .. g .. "_" .. (p + 1) end
	if p > 1 then n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_P" .. g .. "_" .. (p - 1)
	else n = n + 1 o[n] = PTNV_T_BACK .. "/main" end
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say("<color=yellow>" .. PTNV_GR[g].title .. "<color>: " .. PTNV_T_PAGEHINT .. lv .. ".", o)
end

function PTNV_Cond(code)
	if code == 1 then
		if date then return tonumber(date("%Y%m%d")) == GetTask(2010) end
		return 1
	end
	if code == 3 then return GetTask(2283) == 0 end
	-- questfix3: Thien Thu seed held with no care step open (Linh Bao 321, Cao Giac 322, Sung Ung Buu 323)
	if code == 4 then return GetTask(321) == 0 and GetTask(322) == 0 and GetTask(323) == 0 end
	return 1
end

function PTNV_Match(q, camp, lv)
	if q.camp >= 0 and q.camp ~= camp then return nil end
	local v = GetTask(q.var)
	if v < q.lo or v > q.hi then return nil end
	if q.v2 > 0 then
		local v2 = GetTask(q.v2)
		if q.m2 > 0 then v2 = mod(v2, q.m2) end
		if v2 < q.lo2 or v2 > q.hi2 then return nil end
	end
	if q.st == 1 and (lv < q.lv or lv > q.lvmax) then return nil end
	if q.cond > 0 and not PTNV_Cond(q.cond) then return nil end
	return 1
end

-- every chain with a step in progress (first matching row per chain): o[i] = { c = chain, r = row }
function PTNV_Active()
	local camp = PTNV_Camp()
	local lv = GetLevel()
	local o = {}
	local n = 0
	local k = 1
	while k <= PTNV_NCO do
		local c = PTNV_CO[k]
		local ch = PTNV_CH[c]
		local r = nil
		if ch.fn then
			local f = getglobal(ch.fn)
			r = f(camp, lv)
		else
			local j = 1
			while j <= ch.n and not r do
				if PTNV_Match(ch.r[j], camp, lv) then r = ch.r[j] end
				j = j + 1
			end
		end
		if r then
			local e = {}
			e.c = c
			e.r = r
			n = n + 1
			o[n] = e
		end
		k = k + 1
	end
	o.n = n
	return o
end

function PTNV_Clip(s, n)
	if strlen(s) > n then return strsub(s, 1, n - 2) .. ".." end
	return s
end

-- one line describing the step of an active entry
function PTNV_StepText(e)
	local r = e.r
	local s = "<color=yellow>" .. PTNV_CH[e.c].title .. "<color>: " .. r.txt
	if r.lv and r.lv > GetLevel() then s = s .. PTNV_T_LVNEED .. r.lv .. ")" end
	if r.farm and r.farm > 0 then
		local f = PTNV_DS[r.farm]
		s = s .. ". " .. PTNV_T_FARM .. f.nm .. " [" .. floor(f.x / 8) .. "," .. floor(f.y / 16) .. "]"
	end
	if r.dest and r.dest > 0 and r.dest ~= r.farm then s = s .. ". " .. PTNV_T_NPC .. PTNV_DS[r.dest].nm .. "." end
	if r.kill == 1 then s = s .. " " .. PTNV_T_KILL end
	return s
end

-- items of a row still required now: o[i] = { it, have, miss }, o.tot = pieces missing, o.kinds = kinds missing
function PTNV_Have(it)
	if it.k == 1 then return HaveEventItemCount(it.g) or 0 end
	if it.k == 3 then
		local ml = HaveMagic(it.lv)
		if ml and ml > 0 then return 1 end
		return HaveNormalItem(6, 1, it.p, -1) or 0
	end
	return HaveNormalItem(it.g, it.d, it.p, it.cl) or 0
end

function PTNV_Need(r)
	local L = r.items
	if not L and r.set > 0 then L = PTNV_IS[r.set] end
	local o = {}
	local n = 0
	o.tot = 0
	o.kinds = 0
	if L then
		local k = 1
		while k <= L.n do
			local it = L[k]
			if it.cv == 0 or PTNV_Bit(GetTask(it.cv), it.cb) then
				local e = {}
				e.it = it
				e.have = PTNV_Have(it)
				e.miss = it.n - e.have
				if e.miss < 0 then e.miss = 0 end
				if e.miss > 0 then o.kinds = o.kinds + 1 end
				o.tot = o.tot + e.miss
				n = n + 1
				o[n] = e
			end
			k = k + 1
		end
	end
	o.n = n
	return o
end

-- create one piece in the bag; 0 if it does not fit (nothing is dropped on the ground)
function PTNV_GiveOne(it)
	if it.k == 1 then return AddEventItem(it.g) or 0 end
	local g, d, p, lv = it.g, it.d, it.p, it.lv
	if it.k == 3 then g, d, p, lv = 6, 1, it.p, 1 end
	if AddNormalItemPile then return AddNormalItemPile(g, d, p, lv, 0, 0) or 0 end
	-- fallback (engine without AddNormalItemPile): like PTAdm_GiveTo, only with a free bag cell
	if CalcFreeItemCellCount() < 1 then return 0 end
	local idx = AddItem(g, d, p, lv, 0, 0)
	if not idx or idx <= 0 then return 0 end
	local mx = GetMaxStackItem(idx)
	if mx and mx > 1 then AddItemIDStack(idx, 0) else AddItemID(idx, 0) end
	return idx
end

