-- Quy Tinh (task 53: GetByte 1 = state, 2 = step 0..35; tower map = floor(step / 6))
function PTNV_X33(camp, lv)
	local v = GetTask(53)
	if v == 0 then return nil end
	local st = GetByte(v, 1)
	local sp = GetByte(v, 2)
	local tw = PTNV_TW[floor(sp / 6) + 1]
	if st == 1 then return PTNV_Row(tw, "mang B\185ch Linh Ph\173\237n t\237i Phong \202n Th\184p", PTNV_X33I(42), 0, 59) end
	if st == 2 then return PTNV_Row(tw, "h\185 Thi\170n C\173\172ng Tinh c\185nh Phong \202n Th\184p", PTNV_X33I(43), 1, 59, tw) end
	if st == 3 then return PTNV_Row(159, "giao Thi\170n C\173\172ng ch\169n kh\221 cho D\173\172ng Ti\212n", PTNV_X33I(44), 0, 59) end
	if st == 0 and sp > 0 and sp < 36 then return PTNV_Row(159, "nh\203n l\173\238t Quy Tinh ti\213p \235 D\173\172ng Ti\212n", nil, 0, 59) end
	return nil
end

