-- Van chuyen (task 2169 = dest city * 100000 + goods * 1000 + count)
function PTNV_X44(camp, lv)
	local v = GetTask(2169)
	if v <= 0 then return nil end
	local city = floor(v / 100000)
	local gd = floor(mod(v, 100000) / 1000)
	local cnt = mod(v, 1000)
	local g = PTNV_VCG[gd]
	local t = nil
	if g and cnt > 0 then
		t = {}
		t.n = 1
		t[1] = PTNV_It(2, 3, g, 0, 0, cnt, 0, 0, 0, PTNV_VCN[gd])
	end
	return PTNV_Row(PTNV_TT[city], "giao h\181ng cho T\185p Th\173\172ng th\181nh \174\221ch", t, 0, 10)
end

-- Thi luyen su do (899 Hoang mac, 900 Dong Hai, 901 Hien Vien, 902 Bang Xuyen: 1..5 maze doctor, 6 giver)
function PTNV_X52(camp, lv)
	local k = 1
	while k <= 4 do
		local v = GetTask(898 + k)
		if v >= 1 and v <= 5 then return PTNV_Row(PTNV_DP[PTNV_TLB[k] + v], "g\198p \167\185i Phu t\199ng m\170 cung (gi\247 hi\214u \248ng th\221 luy\214n)", nil, 0, 20) end
		if v == 6 then return PTNV_Row(PTNV_TLG[k], "v\210 tr\182 th\221 luy\214n", nil, 0, 20) end
		k = k + 1
	end
	return nil
end

-- Giang Son Y Cuu (2355 step, 2356 state 0 accept / 1 fight / 2 report, 2360 = 1 finished)
function PTNV_X70(camp, lv)
	if GetTask(2360) == 1 then return nil end
	local s = GetTask(2355)
	local st = GetTask(2356)
	if s < 1 or s > 19 then return nil end
	if st == 1 then return PTNV_Row(PTNV_GS[s], "b\173\237c " .. s .. ": t\249 h\185 qu\184i \235 b\183i \174\173\238c giao", nil, 1, 30, PTNV_GS[s]) end
	if st == 2 then return PTNV_Row(172, "b\184o D\173 Kh\184nh b\173\237c " .. s, nil, 0, 30) end
	return PTNV_Row(172, "nh\203n \235 D\173 Kh\184nh b\173\237c " .. s, nil, 0, 30)
end

